// Deduplicate questions by leetcode_id
const seenIds = new Set();
const verifiedQuestions = [];
let duplicatesCount = 0;
let invalidUrlsCount = 0;
let premiumCount = 0;

for (const q of rawQuestions) {
  const [leetcode_id, title, title_slug, is_premium, topic_keys] = q;
  if (seenIds.has(leetcode_id)) {
    duplicatesCount++;
    continue;
  }
  seenIds.add(leetcode_id);

  const problem_url = `https://leetcode.com/problems/${title_slug}/`;
  if (!problem_url.startsWith('https://leetcode.com/problems/')) {
    invalidUrlsCount++;
  }
  if (is_premium) premiumCount++;

  // Ensure topic tags match known topics or map cleanly
  const formattedTopics = topic_keys.map(k => {
    const found = topics.find(t => t.id === k || t.slug === k);
    return found ? found.name : k;
  });

  verifiedQuestions.push({
    id: `q-${leetcode_id}`,
    leetcode_id,
    title,
    title_slug,
    problem_url,
    difficulty: 'Easy',
    topics: formattedTopics,
    topic_ids: topic_keys,
    is_premium,
    source: 'LeetCode Problemset Verified (kaysss/leetcode-problem-set & official)',
    verified_at: '2026-11-12T01:30:00.000Z',
    is_active: true
  });
}

