console.log(`DUPLICATES PREVENTED: ${duplicatesCount}`);
console.log(`PREMIUM QUESTIONS IDENTIFIED: ${premiumCount}`);
console.log(`FREE QUESTIONS: ${verifiedQuestions.length - premiumCount}`);
console.log(`MINIMUM REQUIREMENT (400+): ${verifiedQuestions.length >= 400 ? 'SATISFIED ✅' : 'FAILED ❌'}`);
console.log(`========================================`);

